import React from "react";

import { ProgressDialogStep, SelectorResult, StudioProApi } from "@mendix/extensions-api";

import { isObjectEqual } from "@src/utils/objectUtils";
import { ConstantValidationError, ConstantValidationErrors } from "@src/utils/validationUtils";
import { createStudioProLogger } from "../../../config/logger";
import { Model, ModelType } from "../../../types/model/model";
import { MxCloudGenAIKeyImportData, MxCloudGenAIModelFields } from "../../../types/model/mxCloudGenAIModel";
import { getConstantValue } from "../../../utils/constantUtils";
import { clearModelDetails } from "../../../utils/modelUtils";
import {
    decodeAndParseKey,
    executeConnectionTest,
    invokeResourceAPI,
    updateModelDetailsFromResourcesAPI,
} from "../../../utils/mxCloudGenAIUtils";

export const handleImportKeyFromPortal = async (
    studioPro: StudioProApi,
    model: Model,
    setKeyValidationError: React.Dispatch<React.SetStateAction<ConstantValidationError | undefined>>,
    setModel: React.Dispatch<React.SetStateAction<Model>>,
    updateModelDocument: (model: Model) => Promise<void>
) => {
    const logger = createStudioProLogger(studioPro);
    let updatedModel: Model | undefined;
    let isImportSuccessful = false;
    let isParsingSuccessful = false;

    try {
        const mxCloudGenAIModelFields = model.providerFields as MxCloudGenAIModelFields;
        const keyValue = await getConstantValue(studioPro, mxCloudGenAIModelFields.key);

        if (!keyValue) {
            throw new Error("No key value found. Please make sure the key constant is correctly configured.");
        }

        // Decode base64 JSON
        const keyData: MxCloudGenAIKeyImportData = decodeAndParseKey(studioPro, keyValue);

        if (keyData.type !== "TEXT_GENERATION") {
            throw new Error(
                `Unsupported key type: ${keyData.type}. Only Text Generation keys are currently supported.`
            );
        }

        // Map JSON fields to model attributes
        const updatedMxCloudGenAIModelFields: MxCloudGenAIModelFields = {
            key: mxCloudGenAIModelFields.key,
            keyId: keyData.keyId || "",
            keyName: keyData.keyName || "",
            resourceName: keyData.name || "",
            environment: keyData.environment || "",
            deepLinkURL: keyData.deepLinkUrl || "",
        };

        updatedModel = {
            ...model,
            name: keyData.model || "",
            displayName: keyData.model || "",
            type:
                keyData.type === "TEXT_GENERATION"
                    ? "Text generation"
                    : keyData.type === "EMBEDDINGS_GENERATION"
                      ? "Embeddings"
                      : ("" as ModelType),
            providerFields: {
                ...updatedMxCloudGenAIModelFields,
            },
        };

        isParsingSuccessful = true;

        // Fetch API response in background and update model when complete
        const resourceAPIResponse = await invokeResourceAPI(studioPro, updatedModel);

        if (typeof resourceAPIResponse !== "string") {
            isImportSuccessful = true;
            updatedModel = updateModelDetailsFromResourcesAPI(updatedModel, resourceAPIResponse);
        } else {
            logger.warn("MxCloudGenAI resource API unavailable. Could not update model details.");
        }
    } catch (error) {
        logger.error("Error during MxCloud GenAI key import:", error);
        setKeyValidationError(ConstantValidationErrors.InvalidContent);
    } finally {
        // if keys cannot be parsed,clear old details
        if (!isParsingSuccessful) {
            updatedModel = clearModelDetails(model);
            setModel(updatedModel);
            updateModelDocument(updatedModel);
        } else if (updatedModel) {
            /* Decide whether there is a need to updated the model:
               - if key can be parsed and imported check if old model is equal to new model
               - if key can be parsed but not imported check if old keyId is the same as new keyId
            */
            const skipUpdate = isImportSuccessful
                ? isObjectEqual(model, updatedModel)
                : (model.providerFields as MxCloudGenAIModelFields)?.keyId ===
                  (updatedModel.providerFields as MxCloudGenAIModelFields)?.keyId;

            if (!skipUpdate) {
                setModel(updatedModel);
                updateModelDocument(updatedModel);
            }
        }
    }
};

export async function handleSelectModelKey(studioPro: StudioProApi, model: Model): Promise<Model | undefined> {
    const selectorResult: SelectorResult = await studioPro.ui.elementSelectors.selectDocument({
        allowNone: true,
        query: { elementType: "Constants$Constant" },
    });

    if (selectorResult.status === "ok") {
        return {
            ...model,
            providerFields: {
                ...model.providerFields,
                key: {
                    documentId: selectorResult.selected.id,
                    qualifiedName: selectorResult.selected.module + "." + selectorResult.selected.name,
                },
            },
        };
    }
    if (selectorResult.status === "none") {
        return { ...model, providerFields: { ...model.providerFields, key: undefined } };
    }
}

export async function handleTestConnection(studioPro: StudioProApi, model: Model): Promise<boolean> {
    const steps: ProgressDialogStep[] = [
        {
            title: "Testing connection",
            description: "Testing connection",
            action: async () => {
                return await executeConnectionTest(studioPro, model);
            },
        },
    ];
    const progressDialogResult = await studioPro.ui.dialogs.showProgressDialog("Testing connection", steps);
    switch (progressDialogResult.result) {
        case "Success":
            return true;
        case "UserCancelled":
            return false;
        case "Failure": {
            const errorMessage =
                "No connection. Make sure you are connected to the internet and check that a valid key is set as value for the selected constant.";
            const errorDetails = progressDialogResult.failedStep?.error ?? "";
            await studioPro.ui.messageBoxes.show("error", errorMessage, errorDetails);
            return false;
        }
    }
}
